using System;
using UnityEngine;
using UnityEngine.Rendering;

namespace Game.Runtime
{
    [RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
    public class FloorGridBuilder : MonoBehaviour
    {
        private const int VerticesPerTile = 4;
        private const int TrianglesPerTile = 6;
        private const int UInt16VertexLimit = 65535;

        [SerializeField, Min(1)] private int _gridSize = 10;
        [SerializeField, Min(0.01f)] private float _tileSize = 1f;
        [SerializeField, Min(0f)] private float _spacing = 0f;
        [SerializeField] private Material _floorMaterial;

        private MeshFilter _meshFilter;
        private MeshRenderer _meshRenderer;
        private Mesh _mesh;

        public int GridSize => _gridSize;
        public float TileSize => _tileSize;
        public float Spacing => _spacing;
        public int TileCount => _gridSize * _gridSize;

        public event Action Built;

        private void Awake()
        {
            _meshFilter = GetComponent<MeshFilter>();
            _meshRenderer = GetComponent<MeshRenderer>();
        }

        private void OnDestroy()
        {
            if (_mesh != null)
            {
                Destroy(_mesh);
            }
        }

        public bool Configure(int gridSize, float tileSize, float spacing)
        {
            if (gridSize <= 0 || tileSize <= 0f || spacing < 0f)
            {
                Debug.LogError($"FloorGridBuilder: invalid configuration gridSize={gridSize}, tileSize={tileSize}, spacing={spacing}.", this);
                return false;
            }

            _gridSize = gridSize;
            _tileSize = tileSize;
            _spacing = spacing;
            return true;
        }

        public bool Build()
        {
            if (_gridSize <= 0 || _tileSize <= 0f || _spacing < 0f)
            {
                Debug.LogError($"FloorGridBuilder: cannot build with gridSize={_gridSize}, tileSize={_tileSize}, spacing={_spacing}.", this);
                return false;
            }

            int tileCount = _gridSize * _gridSize;
            int vertexCount = tileCount * VerticesPerTile;

            var vertices = new Vector3[vertexCount];
            var normals = new Vector3[vertexCount];
            var uvs = new Vector2[vertexCount];
            var triangles = new int[tileCount * TrianglesPerTile];

            float pitch = _tileSize + _spacing;
            float half = _gridSize * pitch * 0.5f;

            int vIndex = 0;
            int tIndex = 0;
            for (int x = 0; x < _gridSize; x++)
            {
                for (int z = 0; z < _gridSize; z++)
                {
                    float originX = x * pitch - half;
                    float originZ = z * pitch - half;

                    vertices[vIndex + 0] = new Vector3(originX, 0f, originZ);
                    vertices[vIndex + 1] = new Vector3(originX, 0f, originZ + _tileSize);
                    vertices[vIndex + 2] = new Vector3(originX + _tileSize, 0f, originZ + _tileSize);
                    vertices[vIndex + 3] = new Vector3(originX + _tileSize, 0f, originZ);

                    normals[vIndex + 0] = Vector3.up;
                    normals[vIndex + 1] = Vector3.up;
                    normals[vIndex + 2] = Vector3.up;
                    normals[vIndex + 3] = Vector3.up;

                    uvs[vIndex + 0] = new Vector2(0f, 0f);
                    uvs[vIndex + 1] = new Vector2(0f, 1f);
                    uvs[vIndex + 2] = new Vector2(1f, 1f);
                    uvs[vIndex + 3] = new Vector2(1f, 0f);

                    triangles[tIndex + 0] = vIndex + 0;
                    triangles[tIndex + 1] = vIndex + 1;
                    triangles[tIndex + 2] = vIndex + 2;
                    triangles[tIndex + 3] = vIndex + 0;
                    triangles[tIndex + 4] = vIndex + 2;
                    triangles[tIndex + 5] = vIndex + 3;

                    vIndex += VerticesPerTile;
                    tIndex += TrianglesPerTile;
                }
            }

            if (_mesh == null)
            {
                _mesh = new Mesh { name = "FloorGridMesh" };
            }
            else
            {
                _mesh.Clear();
            }

            // A single combined mesh keeps this a 1 draw call grid regardless of size,
            // instead of one Renderer per tile. UInt32 indices let it scale past 65535 verts.
            _mesh.indexFormat = vertexCount > UInt16VertexLimit ? IndexFormat.UInt32 : IndexFormat.UInt16;
            _mesh.vertices = vertices;
            _mesh.normals = normals;
            _mesh.uv = uvs;
            _mesh.triangles = triangles;
            _mesh.RecalculateBounds();

            _meshFilter.sharedMesh = _mesh;
            if (_floorMaterial != null)
            {
                _meshRenderer.sharedMaterial = _floorMaterial;
            }

            Built?.Invoke();
            return true;
        }
    }
}
