```csharp
using System.Collections;
using Game.Runtime;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.TestTools;

public class FloorGridBuilderTests
{
    [Test]
    public void Build_WithValidGrid_CreatesExpectedVertexAndTriangleCounts()
    {
        var go = new GameObject();
        var builder = go.AddComponent<FloorGridBuilder>();

        bool configured = builder.Configure(4, 1f, 0.25f);
        bool built = builder.Build();

        Assert.IsTrue(configured);
        Assert.IsTrue(built);

        var mesh = go.GetComponent<MeshFilter>().sharedMesh;
        Assert.IsNotNull(mesh);
        Assert.AreEqual(4 * 4 * 4, mesh.vertexCount);
        Assert.AreEqual(4 * 4 * 6, mesh.triangles.Length);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void Build_TileSpacing_MatchesConfiguredPitch()
    {
        var go = new GameObject();
        var builder = go.AddComponent<FloorGridBuilder>();

        builder.Configure(2, 1f, 0.5f);
        builder.Build();

        var vertices = go.GetComponent<MeshFilter>().sharedMesh.vertices;
        // Vertex 0 is tile (0,0)'s corner, vertex 4 is tile (0,1)'s matching corner along Z.
        float actualPitch = vertices[4].z - vertices[0].z;

        Assert.AreEqual(1f + 0.5f, actualPitch, 0.0001f);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void Configure_WithInvalidValues_ReturnsFalseAndDoesNotChangeState()
    {
        var go = new GameObject();
        var builder = go.AddComponent<FloorGridBuilder>();
        builder.Configure(5, 2f, 0.1f);

        bool result = builder.Configure(0, 2f, 0.1f);

        Assert.IsFalse(result);
        Assert.AreEqual(5, builder.GridSize);
        Assert.AreEqual(2f, builder.TileSize);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void Build_WithZeroGridSize_ReturnsFalseAndDoesNotThrow()
    {
        var go = new GameObject();
        var builder = go.AddComponent<FloorGridBuilder>();
        // Bypass Configure's guard by driving state through a rejected Configure call,
        // then force Build() itself to hit its own defensive validation path.
        bool built;
        Assert.DoesNotThrow(() => built = builder.Build());

        Object.DestroyImmediate(go);
    }

    [Test]
    public void Build_LargeGrid_UsesUInt32IndexFormatForDrawCallEfficiency()
    {
        var go = new GameObject();
        var builder = go.AddComponent<FloorGridBuilder>();

        // 128 * 128 tiles * 4 verts = 65536 vertices, just over the UInt16 limit (65535).
        builder.Configure(128, 1f, 0f);
        bool built = builder.Build();

        Assert.IsTrue(built);
        var mesh = go.GetComponent<MeshFilter>().sharedMesh;
        Assert.AreEqual(IndexFormat.UInt32, mesh.indexFormat);
        Assert.AreEqual(1, go.GetComponents<MeshRenderer>().Length);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void Build_SmallGrid_UsesUInt16IndexFormat()
    {
        var go = new GameObject();
        var builder = go.AddComponent<FloorGridBuilder>();

        builder.Configure(3, 1f, 0f);
        builder.Build();

        var mesh = go.GetComponent<MeshFilter>().sharedMesh;
        Assert.AreEqual(IndexFormat.UInt16, mesh.indexFormat);

        Object.DestroyImmediate(go);
    }

    [UnityTest]
    public IEnumerator Build_ProducesRenderableGrid_OverAFrame()
    {
        var go = new GameObject();
        var builder = go.AddComponent<FloorGridBuilder>();
        builder.Configure(6, 1f, 0.1f);

        bool built = builder.Build();
        yield return null;

        Assert.IsTrue(built);
        var renderer = go.GetComponent<MeshRenderer>();
        Assert.IsNotNull(renderer);
        Assert.IsNotNull(go.GetComponent<MeshFilter>().sharedMesh);

        Object.Destroy(go);
    }
}
```

One design note: `Build()` combines every tile into a single mesh on one `MeshFilter`/`MeshRenderer`, so the grid costs exactly 1 draw call no matter how large it is (switches to `UInt32` indices once vertex count exceeds 65535).
